/**

 * File: GIF Output

 *

 * Write GIF images.

 */



#ifdef HAVE_CONFIG_H

#include "config.h"

#endif



#include <stdio.h>

#include <math.h>

#include <string.h>

#include <stdlib.h>

#include "gd.h"

#include "gdhelpers.h"



