	  return error;

	break;

  case KeyPress:

  case KeyRelease:

	if ((error = do_recv_XKeyEvent(message, event)) < 0)

	  return error;

	break;

  default:

	return RPC_ERROR_GENERIC;

  }



  return RPC_ERROR_NO_ERROR;

}





