#define MAX_GLYPHS_INITIAL 1024

#define MAX_LINES_INITIAL 64

#define MAX_BITMAPS_INITIAL 16

#define MAX_SUB_BITMAPS_INITIAL 64

#define SUBPIXEL_MASK 63

