    assert(rv == STDERR_FILENO);

    rv = close(newfile);

    assert(rv == 0);



    errno = EIO;

    vperror("Old McDonald had a farm.  %s", "EI EIO");



    /* Restore stderr */

    rv = dup2(oldstderr, STDERR_FILENO);

    assert(rv == STDERR_FILENO);





    /* Go read the file */

