	ASN1_SIMPLE(DSA, version, LONG),

	ASN1_SIMPLE(DSA, p, BIGNUM),

	ASN1_SIMPLE(DSA, q, BIGNUM),

	ASN1_SIMPLE(DSA, g, BIGNUM),

	ASN1_SIMPLE(DSA, pub_key, BIGNUM),

