#define SMKTREE_BITS 9

#define SMK_NODE 0x80000000





typedef struct SmackVContext {

    AVCodecContext *avctx;

    AVFrame *pic;



    int *mmap_tbl, *mclr_tbl, *full_tbl, *type_tbl;

    int mmap_last[3], mclr_last[3], full_last[3], type_last[3];

