    SMK_BLK_MONO = 0,

    SMK_BLK_FULL = 1,

    SMK_BLK_SKIP = 2,

    SMK_BLK_FILL = 3 };



/**

 * Decode local frame tree

 */

static int smacker_decode_tree(BitstreamContext *bc, HuffContext *hc,

                               uint32_t prefix, int length)

{

    if (!bitstream_read_bit(bc)) { // Leaf

        if(hc->current >= 256){

            av_log(NULL, AV_LOG_ERROR, "Tree size exceeded!\n");

            return AVERROR_INVALIDDATA;

        }

        if(length){

            hc->bits[hc->current] = prefix;

            hc->lengths[hc->current] = length;

        } else {

            hc->bits[hc->current] = 0;

            hc->lengths[hc->current] = 0;

        }

        hc->values[hc->current] = bitstream_read(bc, 8);

        hc->current++;

        if(hc->maxlength < length)

            hc->maxlength = length;

        return 0;

    } else { //Node

        int r;

        length++;

        r = smacker_decode_tree(bc, hc, prefix, length);

        if(r)

            return r;

        return smacker_decode_tree(bc, hc, prefix | (1 << (length - 1)), length);

    }

}



/**

 * Decode header tree

 */

static int smacker_decode_bigtree(BitstreamContext *bc, HuffContext *hc,

                                  DBCtx *ctx)

{

    if (hc->current + 1 >= hc->length) {

        av_log(NULL, AV_LOG_ERROR, "Tree size exceeded!\n");

        return AVERROR_INVALIDDATA;

    }

    if (!bitstream_read_bit(bc)) { // Leaf

        int val, i1, i2;

        i1 = ctx->v1->table ? bitstream_read_vlc(bc, ctx->v1->table, SMKTREE_BITS, 3) : 0;

        i2 = ctx->v2->table ? bitstream_read_vlc(bc, ctx->v2->table, SMKTREE_BITS, 3) : 0;

        if (i1 < 0 || i2 < 0)

            return AVERROR_INVALIDDATA;

        val = ctx->recode1[i1] | (ctx->recode2[i2] << 8);

        if(val == ctx->escapes[0]) {

            ctx->last[0] = hc->current;

            val = 0;

        } else if(val == ctx->escapes[1]) {

            ctx->last[1] = hc->current;

            val = 0;

        } else if(val == ctx->escapes[2]) {

            ctx->last[2] = hc->current;

            val = 0;

        }



        hc->values[hc->current++] = val;

        return 1;

    } else { //Node

        int r = 0, r_new, t;



        t = hc->current++;

        r = smacker_decode_bigtree(bc, hc, ctx);

        if(r < 0)

            return r;

        hc->values[t] = SMK_NODE | r;

        r++;

        r_new = smacker_decode_bigtree(bc, hc, ctx);

        if (r_new < 0)

            return r_new;

        return r + r_new;

    }

}



/**

 * Store large tree as Libav's vlc codes

 */

static int smacker_decode_header_tree(SmackVContext *smk, BitstreamContext *bc,

                                      int **recodes, int *last, int size)

{

    int res;

    HuffContext huff;

    HuffContext tmp1, tmp2;

    VLC vlc[2] = { { 0 } };

    int escapes[3];

    DBCtx ctx;

    int err = 0;



    if(size >= UINT_MAX>>4){ // (((size + 3) >> 2) + 3) << 2 must not overflow

        av_log(smk->avctx, AV_LOG_ERROR, "size too large\n");

        return AVERROR_INVALIDDATA;

    }



    tmp1.length = 256;

    tmp1.maxlength = 0;

    tmp1.current = 0;

    tmp1.bits = av_mallocz(256 * 4);

    tmp1.lengths = av_mallocz(256 * sizeof(int));

    tmp1.values = av_mallocz(256 * sizeof(int));



    tmp2.length = 256;

    tmp2.maxlength = 0;

    tmp2.current = 0;

    tmp2.bits = av_mallocz(256 * 4);

    tmp2.lengths = av_mallocz(256 * sizeof(int));

    tmp2.values = av_mallocz(256 * sizeof(int));

    if (!tmp1.bits || !tmp1.lengths || !tmp1.values ||

        !tmp2.bits || !tmp2.lengths || !tmp2.values) {

        err = AVERROR(ENOMEM);

        goto error;

    }



    if (bitstream_read_bit(bc)) {

        smacker_decode_tree(bc, &tmp1, 0, 0);

        bitstream_skip(bc, 1);

        res = init_vlc(&vlc[0], SMKTREE_BITS, tmp1.length,

                    tmp1.lengths, sizeof(int), sizeof(int),

                    tmp1.bits, sizeof(uint32_t), sizeof(uint32_t), INIT_VLC_LE);

        if(res < 0) {

            av_log(smk->avctx, AV_LOG_ERROR, "Cannot build VLC table\n");

            err = res;

            goto error;

        }

    } else {

        av_log(smk->avctx, AV_LOG_ERROR, "Skipping low bytes tree\n");

    }

    if (bitstream_read_bit(bc)) {

        smacker_decode_tree(bc, &tmp2, 0, 0);

        bitstream_skip(bc, 1);

        res = init_vlc(&vlc[1], SMKTREE_BITS, tmp2.length,

                    tmp2.lengths, sizeof(int), sizeof(int),

                    tmp2.bits, sizeof(uint32_t), sizeof(uint32_t), INIT_VLC_LE);

        if(res < 0) {

            av_log(smk->avctx, AV_LOG_ERROR, "Cannot build VLC table\n");

            err = res;

            goto error;

        }

    } else {

        av_log(smk->avctx, AV_LOG_ERROR, "Skipping high bytes tree\n");

    }



    escapes[0]  = bitstream_read(bc, 8);

    escapes[0] |= bitstream_read(bc, 8) << 8;

    escapes[1]  = bitstream_read(bc, 8);

    escapes[1] |= bitstream_read(bc, 8) << 8;

    escapes[2]  = bitstream_read(bc, 8);

    escapes[2] |= bitstream_read(bc, 8) << 8;



    last[0] = last[1] = last[2] = -1;



    ctx.escapes[0] = escapes[0];

    ctx.escapes[1] = escapes[1];

    ctx.escapes[2] = escapes[2];

    ctx.v1 = &vlc[0];

    ctx.v2 = &vlc[1];

    ctx.recode1 = tmp1.values;

    ctx.recode2 = tmp2.values;

    ctx.last = last;



    huff.length = ((size + 3) >> 2) + 4;

    huff.maxlength = 0;

    huff.current = 0;

    huff.values = av_mallocz(huff.length * sizeof(int));

    if (!huff.values) {

        err = AVERROR(ENOMEM);

        goto error;

    }



    if ((res = smacker_decode_bigtree(bc, &huff, &ctx)) < 0)

        err = res;

    bitstream_skip(bc, 1);

    if(ctx.last[0] == -1) ctx.last[0] = huff.current++;

    if(ctx.last[1] == -1) ctx.last[1] = huff.current++;

    if(ctx.last[2] == -1) ctx.last[2] = huff.current++;

    if (ctx.last[0] >= huff.length ||

        ctx.last[1] >= huff.length ||

        ctx.last[2] >= huff.length) {

        av_log(smk->avctx, AV_LOG_ERROR, "Huffman codes out of range\n");

        err = AVERROR_INVALIDDATA;

    }



    *recodes = huff.values;



error:

    if(vlc[0].table)

        ff_free_vlc(&vlc[0]);

    if(vlc[1].table)

        ff_free_vlc(&vlc[1]);

    av_free(tmp1.bits);

    av_free(tmp1.lengths);

    av_free(tmp1.values);

    av_free(tmp2.bits);

    av_free(tmp2.lengths);

    av_free(tmp2.values);



    return err;

}



static int decode_header_trees(SmackVContext *smk) {

    BitstreamContext bc;

    int mmap_size, mclr_size, full_size, type_size, ret;



    mmap_size = AV_RL32(smk->avctx->extradata);

    mclr_size = AV_RL32(smk->avctx->extradata + 4);

    full_size = AV_RL32(smk->avctx->extradata + 8);

    type_size = AV_RL32(smk->avctx->extradata + 12);



    bitstream_init8(&bc, smk->avctx->extradata + 16, smk->avctx->extradata_size - 16);



    if (!bitstream_read_bit(&bc)) {

        av_log(smk->avctx, AV_LOG_INFO, "Skipping MMAP tree\n");

        smk->mmap_tbl = av_malloc(sizeof(int) * 2);

        if (!smk->mmap_tbl)

            return AVERROR(ENOMEM);

        smk->mmap_tbl[0] = 0;

        smk->mmap_last[0] = smk->mmap_last[1] = smk->mmap_last[2] = 1;

    } else {

        if ((ret = smacker_decode_header_tree(smk, &bc, &smk->mmap_tbl, smk->mmap_last, mmap_size)) < 0)

            return ret;

    }

    if (!bitstream_read_bit(&bc)) {

        av_log(smk->avctx, AV_LOG_INFO, "Skipping MCLR tree\n");

        smk->mclr_tbl = av_malloc(sizeof(int) * 2);

        if (!smk->mclr_tbl)

            return AVERROR(ENOMEM);

        smk->mclr_tbl[0] = 0;

        smk->mclr_last[0] = smk->mclr_last[1] = smk->mclr_last[2] = 1;

    } else {

        if ((ret = smacker_decode_header_tree(smk, &bc, &smk->mclr_tbl, smk->mclr_last, mclr_size)) < 0)

            return ret;

    }

    if (!bitstream_read_bit(&bc)) {

        av_log(smk->avctx, AV_LOG_INFO, "Skipping FULL tree\n");

        smk->full_tbl = av_malloc(sizeof(int) * 2);

        if (!smk->full_tbl)

            return AVERROR(ENOMEM);

        smk->full_tbl[0] = 0;

        smk->full_last[0] = smk->full_last[1] = smk->full_last[2] = 1;

    } else {

        if ((ret = smacker_decode_header_tree(smk, &bc, &smk->full_tbl, smk->full_last, full_size)) < 0)

            return ret;

    }

    if (!bitstream_read_bit(&bc)) {

        av_log(smk->avctx, AV_LOG_INFO, "Skipping TYPE tree\n");

        smk->type_tbl = av_malloc(sizeof(int) * 2);

        if (!smk->type_tbl)

            return AVERROR(ENOMEM);

        smk->type_tbl[0] = 0;

        smk->type_last[0] = smk->type_last[1] = smk->type_last[2] = 1;

    } else {

        if ((ret = smacker_decode_header_tree(smk, &bc, &smk->type_tbl, smk->type_last, type_size)) < 0)

            return ret;

    }



    return 0;

}



static av_always_inline void last_reset(int *recode, int *last) {

    recode[last[0]] = recode[last[1]] = recode[last[2]] = 0;

}



/* get code and update history */

static av_always_inline int smk_get_code(BitstreamContext *bc, int *recode,

                                         int *last)

{

    register int *table = recode;

    int v;



    while(*table & SMK_NODE) {

        if (bitstream_read_bit(bc))

            table += (*table) & (~SMK_NODE);

        table++;

    }

    v = *table;



    if(v != recode[last[0]]) {

        recode[last[2]] = recode[last[1]];

        recode[last[1]] = recode[last[0]];

        recode[last[0]] = v;

    }

    return v;

}



static int decode_frame(AVCodecContext *avctx, void *data, int *got_frame,

                        AVPacket *avpkt)

{

    SmackVContext * const smk = avctx->priv_data;

    uint8_t *out;

    uint32_t *pal;

    GetByteContext gb2;

    BitstreamContext bc;

    int blocks, blk, bw, bh;

    int i, ret;

    int stride;

    int flags;



    if (avpkt->size <= 769)

        return 0;



    if ((ret = ff_reget_buffer(avctx, smk->pic)) < 0) {

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return ret;

    }



    /* make the palette available on the way out */

    pal = (uint32_t*)smk->pic->data[1];

    bytestream2_init(&gb2, avpkt->data, avpkt->size);

    flags = bytestream2_get_byteu(&gb2);

    smk->pic->palette_has_changed = flags & 1;

    smk->pic->key_frame = !!(flags & 2);

    if(smk->pic->key_frame)

        smk->pic->pict_type = AV_PICTURE_TYPE_I;

    else

        smk->pic->pict_type = AV_PICTURE_TYPE_P;



    for(i = 0; i < 256; i++)

        *pal++ = bytestream2_get_be24u(&gb2);



    last_reset(smk->mmap_tbl, smk->mmap_last);

    last_reset(smk->mclr_tbl, smk->mclr_last);

    last_reset(smk->full_tbl, smk->full_last);

    last_reset(smk->type_tbl, smk->type_last);

    bitstream_init8(&bc, avpkt->data + 769, avpkt->size - 769);



    blk = 0;

    bw = avctx->width >> 2;

    bh = avctx->height >> 2;

    blocks = bw * bh;

    out = smk->pic->data[0];

    stride = smk->pic->linesize[0];

    while(blk < blocks) {

        int type, run, mode;

        uint16_t pix;



        type = smk_get_code(&bc, smk->type_tbl, smk->type_last);

        run = block_runs[(type >> 2) & 0x3F];

        switch(type & 3){

        case SMK_BLK_MONO:

            while(run-- && blk < blocks){

                int clr, map;

                int hi, lo;

                clr = smk_get_code(&bc, smk->mclr_tbl, smk->mclr_last);

                map = smk_get_code(&bc, smk->mmap_tbl, smk->mmap_last);

                out = smk->pic->data[0] + (blk / bw) * (stride * 4) + (blk % bw) * 4;

                hi = clr >> 8;

                lo = clr & 0xFF;

                for(i = 0; i < 4; i++) {

                    if(map & 1) out[0] = hi; else out[0] = lo;

                    if(map & 2) out[1] = hi; else out[1] = lo;

                    if(map & 4) out[2] = hi; else out[2] = lo;

                    if(map & 8) out[3] = hi; else out[3] = lo;

                    map >>= 4;

                    out += stride;

                }

                blk++;

            }

            break;

        case SMK_BLK_FULL:

            mode = 0;

            if(avctx->codec_tag == MKTAG('S', 'M', 'K', '4')) { // In case of Smacker v4 we have three modes

                if (bitstream_read_bit(&bc))

                    mode = 1;

                else if (bitstream_read_bit(&bc))

                    mode = 2;

            }

            while(run-- && blk < blocks){

                out = smk->pic->data[0] + (blk / bw) * (stride * 4) + (blk % bw) * 4;

                switch(mode){

                case 0:

                    for(i = 0; i < 4; i++) {

                        pix = smk_get_code(&bc, smk->full_tbl, smk->full_last);

                        AV_WL16(out+2,pix);

                        pix = smk_get_code(&bc, smk->full_tbl, smk->full_last);

                        AV_WL16(out,pix);

                        out += stride;

                    }

                    break;

                case 1:

                    pix = smk_get_code(&bc, smk->full_tbl, smk->full_last);

                    out[0] = out[1] = pix & 0xFF;

                    out[2] = out[3] = pix >> 8;

                    out += stride;

                    out[0] = out[1] = pix & 0xFF;

                    out[2] = out[3] = pix >> 8;

                    out += stride;

                    pix = smk_get_code(&bc, smk->full_tbl, smk->full_last);

                    out[0] = out[1] = pix & 0xFF;

                    out[2] = out[3] = pix >> 8;

                    out += stride;

                    out[0] = out[1] = pix & 0xFF;

                    out[2] = out[3] = pix >> 8;

                    out += stride;

                    break;

                case 2:

                    for(i = 0; i < 2; i++) {

                        uint16_t pix1, pix2;

                        pix2 = smk_get_code(&bc, smk->full_tbl, smk->full_last);

                        pix1 = smk_get_code(&bc, smk->full_tbl, smk->full_last);

                        AV_WL16(out,pix1);

                        AV_WL16(out+2,pix2);

                        out += stride;

                        AV_WL16(out,pix1);

                        AV_WL16(out+2,pix2);

                        out += stride;

                    }

                    break;

                }

                blk++;

            }

            break;

        case SMK_BLK_SKIP:

            while(run-- && blk < blocks)

                blk++;

            break;

        case SMK_BLK_FILL:

            mode = type >> 8;

            while(run-- && blk < blocks){

                uint32_t col;

                out = smk->pic->data[0] + (blk / bw) * (stride * 4) + (blk % bw) * 4;

                col = mode * 0x01010101;

                for(i = 0; i < 4; i++) {

                    *((uint32_t*)out) = col;

                    out += stride;

                }

                blk++;

            }

            break;

        }



    }



    if ((ret = av_frame_ref(data, smk->pic)) < 0)

        return ret;



    *got_frame = 1;



    /* always report that the buffer was completely consumed */

    return avpkt->size;

}





static av_cold int decode_end(AVCodecContext *avctx)

{

    SmackVContext * const smk = avctx->priv_data;



    av_freep(&smk->mmap_tbl);

    av_freep(&smk->mclr_tbl);

    av_freep(&smk->full_tbl);

    av_freep(&smk->type_tbl);



    av_frame_free(&smk->pic);



    return 0;

}





static av_cold int decode_init(AVCodecContext *avctx)

{

    SmackVContext * const c = avctx->priv_data;

    int ret;



    c->avctx = avctx;



    avctx->pix_fmt = AV_PIX_FMT_PAL8;



    c->pic = av_frame_alloc();

    if (!c->pic)

        return AVERROR(ENOMEM);



    /* decode huffman trees from extradata */

    if(avctx->extradata_size < 16){

        av_log(avctx, AV_LOG_ERROR, "Extradata missing!\n");

        return AVERROR_INVALIDDATA;

    }



    if ((ret = decode_header_trees(c))) {

        decode_end(avctx);

        return ret;

    }



    return 0;

}







static av_cold int smka_decode_init(AVCodecContext *avctx)

{

    if (avctx->channels < 1 || avctx->channels > 2) {

        av_log(avctx, AV_LOG_ERROR, "invalid number of channels\n");

        return AVERROR_INVALIDDATA;

    }

    avctx->channel_layout = (avctx->channels==2) ? AV_CH_LAYOUT_STEREO : AV_CH_LAYOUT_MONO;

    avctx->sample_fmt = avctx->bits_per_coded_sample == 8 ? AV_SAMPLE_FMT_U8 : AV_SAMPLE_FMT_S16;



    return 0;

}



/**

 * Decode Smacker audio data

 */

static int smka_decode_frame(AVCodecContext *avctx, void *data,

                             int *got_frame_ptr, AVPacket *avpkt)

{

    AVFrame *frame     = data;

    const uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    BitstreamContext bc;

    HuffContext h[4] = { { 0 } };

    VLC vlc[4]       = { { 0 } };

    int16_t *samples;

    uint8_t *samples8;

    int val;

    int i, res, ret;

    int unp_size;

    int bits, stereo;

    int pred[2] = {0, 0};



    if (buf_size <= 4) {

        av_log(avctx, AV_LOG_ERROR, "packet is too small\n");

        return AVERROR_INVALIDDATA;

    }



    unp_size = AV_RL32(buf);



    bitstream_init8(&bc, buf + 4, buf_size - 4);



    if (!bitstream_read_bit(&bc)) {

        av_log(avctx, AV_LOG_INFO, "Sound: no data\n");

        *got_frame_ptr = 0;

        return 1;

    }

    stereo = bitstream_read_bit(&bc);

    bits   = bitstream_read_bit(&bc);

    if (stereo ^ (avctx->channels != 1)) {

        av_log(avctx, AV_LOG_ERROR, "channels mismatch\n");

        return AVERROR_INVALIDDATA;

    }

    if (bits && avctx->sample_fmt == AV_SAMPLE_FMT_U8) {

        av_log(avctx, AV_LOG_ERROR, "sample format mismatch\n");

        return AVERROR_INVALIDDATA;

    }

    if (unp_size % (avctx->channels * (bits + 1))) {

        av_log(avctx, AV_LOG_ERROR,

               "The buffer does not contain an integer number of samples\n");

        return AVERROR_INVALIDDATA;

    }



    /* get output buffer */

    frame->nb_samples = unp_size / (avctx->channels * (bits + 1));

    if ((ret = ff_get_buffer(avctx, frame, 0)) < 0) {

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return ret;

    }

    samples  = (int16_t *)frame->data[0];

    samples8 =            frame->data[0];



    // Initialize

    for(i = 0; i < (1 << (bits + stereo)); i++) {

        h[i].length = 256;

        h[i].maxlength = 0;

        h[i].current = 0;

        h[i].bits = av_mallocz(256 * 4);

        h[i].lengths = av_mallocz(256 * sizeof(int));

        h[i].values = av_mallocz(256 * sizeof(int));

        if (!h[i].bits || !h[i].lengths || !h[i].values) {

            ret = AVERROR(ENOMEM);

            goto error;

        }

        bitstream_skip(&bc, 1);

        if (smacker_decode_tree(&bc, &h[i], 0, 0) < 0) {

            ret = AVERROR_INVALIDDATA;

            goto error;

        }

        bitstream_skip(&bc, 1);

        if(h[i].current > 1) {

            res = init_vlc(&vlc[i], SMKTREE_BITS, h[i].length,

                    h[i].lengths, sizeof(int), sizeof(int),

                    h[i].bits, sizeof(uint32_t), sizeof(uint32_t), INIT_VLC_LE);

            if(res < 0) {

                av_log(avctx, AV_LOG_ERROR, "Cannot build VLC table\n");

                ret = AVERROR_INVALIDDATA;

                goto error;

            }

        }

    }

    /* this codec relies on wraparound instead of clipping audio */

    if(bits) { //decode 16-bit data

        for(i = stereo; i >= 0; i--)

            pred[i] = sign_extend(av_bswap16(bitstream_read(&bc, 16)), 16);

        for(i = 0; i <= stereo; i++)

            *samples++ = pred[i];

        for(; i < unp_size / 2; i++) {

            if(i & stereo) {

                if(vlc[2].table)

                    res = bitstream_read_vlc(&bc, vlc[2].table, SMKTREE_BITS, 3);

                else

                    res = 0;

                val  = h[2].values[res];

                if(vlc[3].table)

                    res = bitstream_read_vlc(&bc, vlc[3].table, SMKTREE_BITS, 3);

                else

                    res = 0;

                val |= h[3].values[res] << 8;

                pred[1] += sign_extend(val, 16);

                *samples++ = pred[1];

            } else {

                if(vlc[0].table)

                    res = bitstream_read_vlc(&bc, vlc[0].table, SMKTREE_BITS, 3);

                else

                    res = 0;

                val  = h[0].values[res];

                if(vlc[1].table)

                    res = bitstream_read_vlc(&bc, vlc[1].table, SMKTREE_BITS, 3);

                else

                    res = 0;

                val |= h[1].values[res] << 8;

                pred[0] += sign_extend(val, 16);

                *samples++ = pred[0];

            }

        }

    } else { //8-bit data

        for(i = stereo; i >= 0; i--)

            pred[i] = bitstream_read(&bc, 8);

        for(i = 0; i <= stereo; i++)

            *samples8++ = pred[i];

        for(; i < unp_size; i++) {

            if(i & stereo){

                if(vlc[1].table)

                    res = bitstream_read_vlc(&bc, vlc[1].table, SMKTREE_BITS, 3);

                else

                    res = 0;

                pred[1] += sign_extend(h[1].values[res], 8);

                *samples8++ = pred[1];

            } else {

                if(vlc[0].table)

                    res = bitstream_read_vlc(&bc, vlc[0].table, SMKTREE_BITS, 3);

                else

                    res = 0;

                pred[0] += sign_extend(h[0].values[res], 8);

                *samples8++ = pred[0];

            }

        }

    }



    *got_frame_ptr = 1;

    ret = buf_size;



error:

    for(i = 0; i < 4; i++) {

        if(vlc[i].table)

            ff_free_vlc(&vlc[i]);

        av_free(h[i].bits);

        av_free(h[i].lengths);

        av_free(h[i].values);

    }



    return ret;

}



