#define MOP_IN(opcode) do {\

  if (opcode == OpPrevTarget) OpPrevCounter[OpCurr]++;\

  OpCurr = opcode;\

  OpCounter[opcode]++;\

  GETTIME(ts);\

} while(0)



#define MOP_OUT do {\

  GETTIME(te);\

  OpTime[OpCurr] += TIMEDIFF(te, ts);\

} while(0)



extern void

onig_statistics_init(void)

{

  int i;

  for (i = 0; i < 256; i++) {

    OpCounter[i] = OpPrevCounter[i] = 0; OpTime[i] = 0;

  }

  MaxStackDepth = 0;

}



extern int

onig_print_statistics(FILE* f)

{

  int r;

  int i;



  r = fprintf(f, "   count      prev        time\n");

  if (r < 0) return -1;



  for (i = 0; OnigOpInfo[i].opcode >= 0; i++) {

    r = fprintf(f, "%8d: %8d: %10ld: %s\n",

                OpCounter[i], OpPrevCounter[i], OpTime[i], OnigOpInfo[i].name);

    if (r < 0) return -1;

  }

  r = fprintf(f, "\nmax stack depth: %d\n", MaxStackDepth);

  if (r < 0) return -1;



  return 0;

}



#define STACK_INC do {\

  stk++;\

  if (stk - stk_base > MaxStackDepth) \

    MaxStackDepth = stk - stk_base;\

} while(0)



#else

#define STACK_INC     stk++



#define MOP_IN(opcode)

#define MOP_OUT

#endif





/* matching region of POSIX API */

typedef int regoff_t;



typedef struct {

  regoff_t  rm_so;

  regoff_t  rm_eo;

} posix_regmatch_t;



/* match data(str - end) from position (sstart). */

/* if sstart == str then set sprev to NULL. */

static int

match_at(regex_t* reg, const UChar* str, const UChar* end,

#ifdef USE_MATCH_RANGE_MUST_BE_INSIDE_OF_SPECIFIED_RANGE

	 const UChar* right_range,

#endif

	 const UChar* sstart, UChar* sprev, OnigMatchArg* msa)

{

  static UChar FinishCode[] = { OP_FINISH };



  int i, n, num_mem, best_len, pop_level;

  LengthType tlen, tlen2;

  MemNumType mem;

  RelAddrType addr;

  UChar *s, *q, *sbegin;

  int is_alloca;

  char *alloc_base;

  OnigStackType *stk_base, *stk, *stk_end;

  OnigStackType *stkp; /* used as any purpose. */

  OnigStackIndex si;

  OnigStackIndex *repeat_stk;

  OnigStackIndex *mem_start_stk, *mem_end_stk;

#ifdef USE_COMBINATION_EXPLOSION_CHECK

  int scv;

  unsigned char* state_check_buff = msa->state_check_buff;

  int num_comb_exp_check = reg->num_comb_exp_check;

#endif

  UChar *p = reg->p;

  OnigOptionType option = reg->options;

  OnigEncoding encode = reg->enc;

  OnigCaseFoldType case_fold_flag = reg->case_fold_flag;



  //n = reg->num_repeat + reg->num_mem * 2;

  pop_level = reg->stack_pop_level;

  num_mem = reg->num_mem;

  STACK_INIT(INIT_MATCH_STACK_SIZE);

  UPDATE_FOR_STACK_REALLOC;

  for (i = 1; i <= num_mem; i++) {

    mem_start_stk[i] = mem_end_stk[i] = INVALID_STACK_INDEX;

  }



#ifdef ONIG_DEBUG_MATCH

  fprintf(stderr, "match_at: str: %d, end: %d, start: %d, sprev: %d\n",

	  (int )str, (int )end, (int )sstart, (int )sprev);

  fprintf(stderr, "size: %d, start offset: %d\n",

	  (int )(end - str), (int )(sstart - str));

#endif



  STACK_PUSH_ENSURED(STK_ALT, FinishCode);  /* bottom stack */

  best_len = ONIG_MISMATCH;

  s = (UChar* )sstart;

  while (1) {

#ifdef ONIG_DEBUG_MATCH

    {

      UChar *q, *bp, buf[50];

      int len;

      fprintf(stderr, "%4d> \"", (int )(s - str));

      bp = buf;

      for (i = 0, q = s; i < 7 && q < end; i++) {

	len = enclen(encode, q);

	while (len-- > 0) *bp++ = *q++;

      }

      if (q < end) { xmemcpy(bp, "...\"", 4); bp += 4; }

      else         { xmemcpy(bp, "\"",    1); bp += 1; }

      *bp = 0;

      fputs((char* )buf, stderr);

      for (i = 0; i < 20 - (bp - buf); i++) fputc(' ', stderr);

      onig_print_compiled_byte_code(stderr, p, NULL, encode);

      fprintf(stderr, "\n");

    }

#endif



    sbegin = s;

    switch (*p++) {

    case OP_END:  MOP_IN(OP_END);

      n = s - sstart;

      if (n > best_len) {

        OnigRegion* region;

#ifdef USE_FIND_LONGEST_SEARCH_ALL_OF_RANGE

        if (IS_FIND_LONGEST(option)) {

          if (n > msa->best_len) {

            msa->best_len = n;

            msa->best_s   = (UChar* )sstart;

          }

          else

            goto end_best_len;

        }

#endif

        best_len = n;

        region = msa->region;

        if (region) {

#ifdef USE_POSIX_API_REGION_OPTION

          if (IS_POSIX_REGION(msa->options)) {

            posix_regmatch_t* rmt = (posix_regmatch_t* )region;



            rmt[0].rm_so = sstart - str;

            rmt[0].rm_eo = s      - str;

            for (i = 1; i <= num_mem; i++) {

              if (mem_end_stk[i] != INVALID_STACK_INDEX) {

                if (BIT_STATUS_AT(reg->bt_mem_start, i))

                  rmt[i].rm_so = STACK_AT(mem_start_stk[i])->u.mem.pstr - str;

                else

                  rmt[i].rm_so = (UChar* )((void* )(mem_start_stk[i])) - str;



                rmt[i].rm_eo = (BIT_STATUS_AT(reg->bt_mem_end, i)

                                ? STACK_AT(mem_end_stk[i])->u.mem.pstr

                                : (UChar* )((void* )mem_end_stk[i])) - str;

              }

              else {

                rmt[i].rm_so = rmt[i].rm_eo = ONIG_REGION_NOTPOS;

              }

            }

          }

          else {

#endif /* USE_POSIX_API_REGION_OPTION */

            region->beg[0] = sstart - str;

            region->end[0] = s      - str;

            for (i = 1; i <= num_mem; i++) {

              if (mem_end_stk[i] != INVALID_STACK_INDEX) {

                if (BIT_STATUS_AT(reg->bt_mem_start, i))

                  region->beg[i] = STACK_AT(mem_start_stk[i])->u.mem.pstr - str;

                else

                  region->beg[i] = (UChar* )((void* )mem_start_stk[i]) - str;



                region->end[i] = (BIT_STATUS_AT(reg->bt_mem_end, i)

                                  ? STACK_AT(mem_end_stk[i])->u.mem.pstr

                                  : (UChar* )((void* )mem_end_stk[i])) - str;

              }

              else {

                region->beg[i] = region->end[i] = ONIG_REGION_NOTPOS;

              }

            }



#ifdef USE_CAPTURE_HISTORY

            if (reg->capture_history != 0) {

              int r;

              OnigCaptureTreeNode* node;



              if (IS_NULL(region->history_root)) {

                region->history_root = node = history_node_new();

                CHECK_NULL_RETURN_MEMERR(node);

              }

              else {

                node = region->history_root;

                history_tree_clear(node);

              }



              node->group = 0;

              node->beg   = sstart - str;

              node->end   = s      - str;



              stkp = stk_base;

              r = make_capture_history_tree(region->history_root, &stkp,

                                            stk, (UChar* )str, reg);

              if (r < 0) {

                best_len = r; /* error code */

                goto finish;

              }

            }

#endif /* USE_CAPTURE_HISTORY */

#ifdef USE_POSIX_API_REGION_OPTION

          } /* else IS_POSIX_REGION() */

#endif

        } /* if (region) */

      } /* n > best_len */



#ifdef USE_FIND_LONGEST_SEARCH_ALL_OF_RANGE

    end_best_len:

#endif

      MOP_OUT;



      if (IS_FIND_CONDITION(option)) {

        if (IS_FIND_NOT_EMPTY(option) && s == sstart) {

          best_len = ONIG_MISMATCH;

          goto fail; /* for retry */

        }

        if (IS_FIND_LONGEST(option) && DATA_ENSURE_CHECK1) {

          goto fail; /* for retry */

        }

      }



      /* default behavior: return first-matching result. */

      goto finish;

      break;



    case OP_EXACT1:  MOP_IN(OP_EXACT1);

      DATA_ENSURE(1);

      if (*p != *s) goto fail;

      p++; s++;

      MOP_OUT;

      break;



    case OP_EXACT1_IC:  MOP_IN(OP_EXACT1_IC);

      {

        int len;

        UChar *q, lowbuf[ONIGENC_MBC_CASE_FOLD_MAXLEN];



        DATA_ENSURE(1);

        len = ONIGENC_MBC_CASE_FOLD(encode,

                 /* DISABLE_CASE_FOLD_MULTI_CHAR(case_fold_flag), */

                                    case_fold_flag,

                                    &s, end, lowbuf);

        DATA_ENSURE(0);

        q = lowbuf;

        while (len-- > 0) {

          if (*p != *q) {

            goto fail;

          }

          p++; q++;

        }

      }

      MOP_OUT;

      break;



    case OP_EXACT2:  MOP_IN(OP_EXACT2);

      DATA_ENSURE(2);

      if (*p != *s) goto fail;

      p++; s++;

      if (*p != *s) goto fail;

      sprev = s;

      p++; s++;

      MOP_OUT;

      continue;

      break;



    case OP_EXACT3:  MOP_IN(OP_EXACT3);

      DATA_ENSURE(3);

      if (*p != *s) goto fail;

      p++; s++;

      if (*p != *s) goto fail;

      p++; s++;

      if (*p != *s) goto fail;

      sprev = s;

      p++; s++;

      MOP_OUT;

      continue;

      break;



    case OP_EXACT4:  MOP_IN(OP_EXACT4);

      DATA_ENSURE(4);

      if (*p != *s) goto fail;

      p++; s++;

      if (*p != *s) goto fail;

      p++; s++;

      if (*p != *s) goto fail;

      p++; s++;

      if (*p != *s) goto fail;

      sprev = s;

      p++; s++;

      MOP_OUT;

      continue;

      break;



    case OP_EXACT5:  MOP_IN(OP_EXACT5);

      DATA_ENSURE(5);

      if (*p != *s) goto fail;

      p++; s++;

      if (*p != *s) goto fail;

      p++; s++;

      if (*p != *s) goto fail;

      p++; s++;

      if (*p != *s) goto fail;

      p++; s++;

      if (*p != *s) goto fail;

      sprev = s;

      p++; s++;

      MOP_OUT;

      continue;

      break;



    case OP_EXACTN:  MOP_IN(OP_EXACTN);

      GET_LENGTH_INC(tlen, p);

      DATA_ENSURE(tlen);

      while (tlen-- > 0) {

        if (*p++ != *s++) goto fail;

      }

      sprev = s - 1;

      MOP_OUT;

      continue;

      break;



    case OP_EXACTN_IC:  MOP_IN(OP_EXACTN_IC);

      {

        int len;

        UChar *q, *endp, lowbuf[ONIGENC_MBC_CASE_FOLD_MAXLEN];



        GET_LENGTH_INC(tlen, p);

        endp = p + tlen;



        while (p < endp) {

          sprev = s;

          DATA_ENSURE(1);

          len = ONIGENC_MBC_CASE_FOLD(encode,

                        /* DISABLE_CASE_FOLD_MULTI_CHAR(case_fold_flag), */

                                      case_fold_flag,

                                      &s, end, lowbuf);

          DATA_ENSURE(0);

          q = lowbuf;

          while (len-- > 0) {

            if (*p != *q) goto fail;

            p++; q++;

          }

        }

      }



      MOP_OUT;

      continue;

      break;



    case OP_EXACTMB2N1:  MOP_IN(OP_EXACTMB2N1);

      DATA_ENSURE(2);

      if (*p != *s) goto fail;

      p++; s++;

      if (*p != *s) goto fail;

      p++; s++;

      MOP_OUT;

      break;



    case OP_EXACTMB2N2:  MOP_IN(OP_EXACTMB2N2);

      DATA_ENSURE(4);

      if (*p != *s) goto fail;

      p++; s++;

      if (*p != *s) goto fail;

      p++; s++;

      sprev = s;

      if (*p != *s) goto fail;

      p++; s++;

      if (*p != *s) goto fail;

      p++; s++;

      MOP_OUT;

      continue;

      break;



    case OP_EXACTMB2N3:  MOP_IN(OP_EXACTMB2N3);

      DATA_ENSURE(6);

      if (*p != *s) goto fail;

      p++; s++;

      if (*p != *s) goto fail;

      p++; s++;

      if (*p != *s) goto fail;

      p++; s++;

      if (*p != *s) goto fail;

      p++; s++;

      sprev = s;

      if (*p != *s) goto fail;

      p++; s++;

      if (*p != *s) goto fail;

      p++; s++;

      MOP_OUT;

      continue;

      break;



    case OP_EXACTMB2N:  MOP_IN(OP_EXACTMB2N);

      GET_LENGTH_INC(tlen, p);

      DATA_ENSURE(tlen * 2);

      while (tlen-- > 0) {

        if (*p != *s) goto fail;

        p++; s++;

        if (*p != *s) goto fail;

        p++; s++;

      }

      sprev = s - 2;

      MOP_OUT;

      continue;

      break;



    case OP_EXACTMB3N:  MOP_IN(OP_EXACTMB3N);

      GET_LENGTH_INC(tlen, p);

      DATA_ENSURE(tlen * 3);

      while (tlen-- > 0) {

        if (*p != *s) goto fail;

        p++; s++;

        if (*p != *s) goto fail;

        p++; s++;

        if (*p != *s) goto fail;

        p++; s++;

      }

      sprev = s - 3;

      MOP_OUT;

      continue;

      break;



    case OP_EXACTMBN:  MOP_IN(OP_EXACTMBN);

      GET_LENGTH_INC(tlen,  p);  /* mb-len */

      GET_LENGTH_INC(tlen2, p);  /* string len */

      tlen2 *= tlen;

      DATA_ENSURE(tlen2);

      while (tlen2-- > 0) {

        if (*p != *s) goto fail;

        p++; s++;

      }

      sprev = s - tlen;

      MOP_OUT;

      continue;

      break;



    case OP_CCLASS:  MOP_IN(OP_CCLASS);

      DATA_ENSURE(1);

      if (BITSET_AT(((BitSetRef )p), *s) == 0) goto fail;

      p += SIZE_BITSET;

      s += enclen(encode, s);   /* OP_CCLASS can match mb-code. \D, \S */

      MOP_OUT;

      break;



    case OP_CCLASS_MB:  MOP_IN(OP_CCLASS_MB);

      if (! ONIGENC_IS_MBC_HEAD(encode, s)) goto fail;



    cclass_mb:

      GET_LENGTH_INC(tlen, p);

      {

        OnigCodePoint code;

        UChar *ss;

        int mb_len;



        DATA_ENSURE(1);

        mb_len = enclen(encode, s);

        DATA_ENSURE(mb_len);

        ss = s;

        s += mb_len;

        code = ONIGENC_MBC_TO_CODE(encode, ss, s);



#ifdef PLATFORM_UNALIGNED_WORD_ACCESS

        if (! onig_is_in_code_range(p, code)) goto fail;

#else

        q = p;

        ALIGNMENT_RIGHT(q);

        if (! onig_is_in_code_range(q, code)) goto fail;

#endif

      }

      p += tlen;

      MOP_OUT;

      break;



    case OP_CCLASS_MIX:  MOP_IN(OP_CCLASS_MIX);

      DATA_ENSURE(1);

      if (ONIGENC_IS_MBC_HEAD(encode, s)) {

        p += SIZE_BITSET;

        goto cclass_mb;

      }

      else {

        if (BITSET_AT(((BitSetRef )p), *s) == 0)

          goto fail;



        p += SIZE_BITSET;

        GET_LENGTH_INC(tlen, p);

        p += tlen;

        s++;

      }

      MOP_OUT;

      break;



    case OP_CCLASS_NOT:  MOP_IN(OP_CCLASS_NOT);

      DATA_ENSURE(1);

      if (BITSET_AT(((BitSetRef )p), *s) != 0) goto fail;

      p += SIZE_BITSET;

      s += enclen(encode, s);

      MOP_OUT;

      break;



    case OP_CCLASS_MB_NOT:  MOP_IN(OP_CCLASS_MB_NOT);

      DATA_ENSURE(1);

      if (! ONIGENC_IS_MBC_HEAD(encode, s)) {

        s++;

        GET_LENGTH_INC(tlen, p);

        p += tlen;

        goto cc_mb_not_success;

      }



    cclass_mb_not:

      GET_LENGTH_INC(tlen, p);

      {

        OnigCodePoint code;

        UChar *ss;

        int mb_len = enclen(encode, s);



        if (! DATA_ENSURE_CHECK(mb_len)) {

          DATA_ENSURE(1);

          s = (UChar* )end;

          p += tlen;

          goto cc_mb_not_success;

        }



        ss = s;

        s += mb_len;

        code = ONIGENC_MBC_TO_CODE(encode, ss, s);



#ifdef PLATFORM_UNALIGNED_WORD_ACCESS

        if (onig_is_in_code_range(p, code)) goto fail;

#else

        q = p;

        ALIGNMENT_RIGHT(q);

        if (onig_is_in_code_range(q, code)) goto fail;

#endif

      }

      p += tlen;



    cc_mb_not_success:

      MOP_OUT;

      break;



    case OP_CCLASS_MIX_NOT:  MOP_IN(OP_CCLASS_MIX_NOT);

      DATA_ENSURE(1);

      if (ONIGENC_IS_MBC_HEAD(encode, s)) {

        p += SIZE_BITSET;

        goto cclass_mb_not;

      }

      else {

        if (BITSET_AT(((BitSetRef )p), *s) != 0)

          goto fail;



        p += SIZE_BITSET;

        GET_LENGTH_INC(tlen, p);

        p += tlen;

        s++;

      }

      MOP_OUT;

      break;



    case OP_CCLASS_NODE:  MOP_IN(OP_CCLASS_NODE);

      {

        OnigCodePoint code;

        void *node;

        int mb_len;

        UChar *ss;



        DATA_ENSURE(1);

        GET_POINTER_INC(node, p);

        mb_len = enclen(encode, s);

        ss = s;

        s += mb_len;

        DATA_ENSURE(0);

        code = ONIGENC_MBC_TO_CODE(encode, ss, s);

        if (onig_is_code_in_cc_len(mb_len, code, node) == 0) goto fail;

      }

      MOP_OUT;

      break;



    case OP_ANYCHAR:  MOP_IN(OP_ANYCHAR);

      DATA_ENSURE(1);

      n = enclen(encode, s);

      DATA_ENSURE(n);

      if (ONIGENC_IS_MBC_NEWLINE(encode, s, end)) goto fail;

      s += n;

      MOP_OUT;

      break;



    case OP_ANYCHAR_ML:  MOP_IN(OP_ANYCHAR_ML);

      DATA_ENSURE(1);

      n = enclen(encode, s);

      DATA_ENSURE(n);

      s += n;

      MOP_OUT;

      break;



    case OP_ANYCHAR_STAR:  MOP_IN(OP_ANYCHAR_STAR);

      while (DATA_ENSURE_CHECK1) {

        STACK_PUSH_ALT(p, s, sprev);

        n = enclen(encode, s);

        DATA_ENSURE(n);

        if (ONIGENC_IS_MBC_NEWLINE(encode, s, end))  goto fail;

        sprev = s;

        s += n;

      }

      MOP_OUT;

      break;



    case OP_ANYCHAR_ML_STAR:  MOP_IN(OP_ANYCHAR_ML_STAR);

      while (DATA_ENSURE_CHECK1) {

        STACK_PUSH_ALT(p, s, sprev);

        n = enclen(encode, s);

        if (n > 1) {

          DATA_ENSURE(n);

          sprev = s;

          s += n;

        }

        else {

          sprev = s;

          s++;

        }

      }

      MOP_OUT;

      break;



    case OP_ANYCHAR_STAR_PEEK_NEXT:  MOP_IN(OP_ANYCHAR_STAR_PEEK_NEXT);

      while (DATA_ENSURE_CHECK1) {

        if (*p == *s) {

          STACK_PUSH_ALT(p + 1, s, sprev);

        }

        n = enclen(encode, s);

        DATA_ENSURE(n);

        if (ONIGENC_IS_MBC_NEWLINE(encode, s, end))  goto fail;

        sprev = s;

        s += n;

      }

      p++;

      MOP_OUT;

      break;



    case OP_ANYCHAR_ML_STAR_PEEK_NEXT:MOP_IN(OP_ANYCHAR_ML_STAR_PEEK_NEXT);

      while (DATA_ENSURE_CHECK1) {

        if (*p == *s) {

          STACK_PUSH_ALT(p + 1, s, sprev);

        }

        n = enclen(encode, s);

        if (n > 1) {

          DATA_ENSURE(n);

          sprev = s;

          s += n;

        }

        else {

          sprev = s;

          s++;

        }

      }

      p++;

      MOP_OUT;

      break;



#ifdef USE_COMBINATION_EXPLOSION_CHECK

    case OP_STATE_CHECK_ANYCHAR_STAR:  MOP_IN(OP_STATE_CHECK_ANYCHAR_STAR);

      GET_STATE_CHECK_NUM_INC(mem, p);

      while (DATA_ENSURE_CHECK1) {

        STATE_CHECK_VAL(scv, mem);

        if (scv) goto fail;



        STACK_PUSH_ALT_WITH_STATE_CHECK(p, s, sprev, mem);

        n = enclen(encode, s);

        DATA_ENSURE(n);

        if (ONIGENC_IS_MBC_NEWLINE(encode, s, end))  goto fail;

        sprev = s;

        s += n;

      }

      MOP_OUT;

      break;



    case OP_STATE_CHECK_ANYCHAR_ML_STAR:

      MOP_IN(OP_STATE_CHECK_ANYCHAR_ML_STAR);



      GET_STATE_CHECK_NUM_INC(mem, p);

      while (DATA_ENSURE_CHECK1) {

        STATE_CHECK_VAL(scv, mem);

        if (scv) goto fail;



        STACK_PUSH_ALT_WITH_STATE_CHECK(p, s, sprev, mem);

        n = enclen(encode, s);

        if (n > 1) {

          DATA_ENSURE(n);

          sprev = s;

          s += n;

        }

        else {

          sprev = s;

          s++;

        }

      }

      MOP_OUT;

      break;

#endif /* USE_COMBINATION_EXPLOSION_CHECK */



    case OP_WORD:  MOP_IN(OP_WORD);

      DATA_ENSURE(1);

      if (! ONIGENC_IS_MBC_WORD(encode, s, end))

        goto fail;



      s += enclen(encode, s);

      MOP_OUT;

      break;



    case OP_NOT_WORD:  MOP_IN(OP_NOT_WORD);

      DATA_ENSURE(1);

      if (ONIGENC_IS_MBC_WORD(encode, s, end))

        goto fail;



      s += enclen(encode, s);

      MOP_OUT;

      break;



    case OP_WORD_BOUND:  MOP_IN(OP_WORD_BOUND);

      if (ON_STR_BEGIN(s)) {

        DATA_ENSURE(1);

        if (! ONIGENC_IS_MBC_WORD(encode, s, end))

          goto fail;

      }

      else if (ON_STR_END(s)) {

        if (! ONIGENC_IS_MBC_WORD(encode, sprev, end))

          goto fail;

      }

      else {

        if (ONIGENC_IS_MBC_WORD(encode, s, end)

            == ONIGENC_IS_MBC_WORD(encode, sprev, end))

          goto fail;

      }

      MOP_OUT;

      continue;

      break;



    case OP_NOT_WORD_BOUND:  MOP_IN(OP_NOT_WORD_BOUND);

      if (ON_STR_BEGIN(s)) {

        if (DATA_ENSURE_CHECK1 && ONIGENC_IS_MBC_WORD(encode, s, end))

