/*

=================

CL_DemoFrameDurationSDev

=================

*/

static float CL_DemoFrameDurationSDev( void )

{

	int i;

	int numFrames;

	float mean = 0.0f;

	float variance = 0.0f;



	if( ( clc.timeDemoFrames - 1 ) > MAX_TIMEDEMO_DURATIONS )

		numFrames = MAX_TIMEDEMO_DURATIONS;

	else

		numFrames = clc.timeDemoFrames - 1;



	for( i = 0; i < numFrames; i++ )

		mean += clc.timeDemoDurations[ i ];

	mean /= numFrames;



	for( i = 0; i < numFrames; i++ )

	{

		float x = clc.timeDemoDurations[ i ];



		variance += ( ( x - mean ) * ( x - mean ) );

	}

	variance /= numFrames;



	return sqrt( variance );

}



/*

=================

CL_DemoCompleted

=================

*/

void CL_DemoCompleted( void )

{

	char buffer[ MAX_STRING_CHARS ];



	if( cl_timedemo && cl_timedemo->integer )

	{

		int	time;



		time = Sys_Milliseconds() - clc.timeDemoStart;

		if( time > 0 )

		{

			// Millisecond times are frame durations:

			// minimum/average/maximum/std deviation

			Com_sprintf( buffer, sizeof( buffer ),

					"%i frames %3.1f seconds %3.1f fps %d.0/%.1f/%d.0/%.1f ms\n",

					clc.timeDemoFrames,

					time/1000.0,

					clc.timeDemoFrames*1000.0 / time,

					clc.timeDemoMinDuration,

					time / (float)clc.timeDemoFrames,

					clc.timeDemoMaxDuration,

					CL_DemoFrameDurationSDev( ) );

			Com_Printf( "%s", buffer );



			// Write a log of all the frame durations

			if( cl_timedemoLog && strlen( cl_timedemoLog->string ) > 0 )

			{

				int i;

				int numFrames;

				fileHandle_t f;



				if( ( clc.timeDemoFrames - 1 ) > MAX_TIMEDEMO_DURATIONS )

					numFrames = MAX_TIMEDEMO_DURATIONS;

				else

					numFrames = clc.timeDemoFrames - 1;



				f = FS_FOpenFileWrite( cl_timedemoLog->string );

				if( f )

				{

					FS_Printf( f, "# %s", buffer );



					for( i = 0; i < numFrames; i++ )

						FS_Printf( f, "%d\n", clc.timeDemoDurations[ i ] );



					FS_FCloseFile( f );

					Com_Printf( "%s written\n", cl_timedemoLog->string );

				}

				else

				{

					Com_Printf( "Couldn't open %s for writing\n",

							cl_timedemoLog->string );

				}

			}

		}

	}



	CL_Disconnect( qtrue );

	CL_NextDemo();

}



/*

=================

CL_ReadDemoMessage

=================

*/

void CL_ReadDemoMessage( void ) {

	int	r;

	msg_t	buf;

	byte	bufData[ MAX_MSGLEN ];

	int	s;



	if ( !clc.demofile ) {

		CL_DemoCompleted();

		return;

	}



	// get the sequence number

	r = FS_Read( &s, 4, clc.demofile );

	if ( r != 4 ) {

		CL_DemoCompleted();

		return;

	}

	clc.serverMessageSequence = LittleLong( s );



	// init the message

	MSG_Init( &buf, bufData, sizeof( bufData ) );



	// get the length

	r = FS_Read( &buf.cursize, 4, clc.demofile );

	if ( r != 4 ) {

		CL_DemoCompleted();

		return;

	}

	buf.cursize = LittleLong( buf.cursize );

	if ( buf.cursize == -1 ) {

		CL_DemoCompleted();

		return;

	}

	if ( buf.cursize > buf.maxsize ) {

		Com_Error( ERR_DROP, "CL_ReadDemoMessage: demoMsglen > MAX_MSGLEN" );

	}

	r = FS_Read( buf.data, buf.cursize, clc.demofile );

	if ( r != buf.cursize ) {

		Com_Printf( "Demo file was truncated.\n" );

		CL_DemoCompleted();

		return;

	}



	clc.lastPacketTime = cls.realtime;

	buf.readcount = 0;

	CL_ParseServerMessage( &buf );

}



/*

====================

CL_WalkDemoExt

====================

*/

static int CL_WalkDemoExt(char *arg, char *name, int *demofile)

{

	int i = 0;

	*demofile = 0;



#ifdef LEGACY_PROTOCOL

	if(com_legacyprotocol->integer > 0)

	{

		Com_sprintf(name, MAX_OSPATH, "demos/%s.%s%d", arg, DEMOEXT, com_legacyprotocol->integer);

		FS_FOpenFileRead(name, demofile, qtrue);



		if (*demofile)

		{

			Com_Printf("Demo file: %s\n", name);

			return com_legacyprotocol->integer;

		}

	}



	if(com_protocol->integer != com_legacyprotocol->integer)

#endif

	{

		Com_sprintf(name, MAX_OSPATH, "demos/%s.%s%d", arg, DEMOEXT, com_protocol->integer);

		FS_FOpenFileRead(name, demofile, qtrue);



		if (*demofile)

		{

			Com_Printf("Demo file: %s\n", name);

			return com_protocol->integer;

		}

	}



	Com_Printf("Not found: %s\n", name);



	while(demo_protocols[i])

	{

#ifdef LEGACY_PROTOCOL

		if(demo_protocols[i] == com_legacyprotocol->integer)

			continue;

#endif

		if(demo_protocols[i] == com_protocol->integer)

			continue;



		Com_sprintf (name, MAX_OSPATH, "demos/%s.%s%d", arg, DEMOEXT, demo_protocols[i]);

		FS_FOpenFileRead( name, demofile, qtrue );

		if (*demofile)

		{

			Com_Printf("Demo file: %s\n", name);



			return demo_protocols[i];

		}

		else

			Com_Printf("Not found: %s\n", name);

		i++;

	}



	return -1;

}



