#define MAX_SERVERSPERPACKET    256



/*

===================

CL_ServersResponsePacket

===================

*/

void CL_ServersResponsePacket( const netadr_t* from, msg_t *msg, qboolean extended ) {

	int				i, j, count, total;

	netadr_t addresses[MAX_SERVERSPERPACKET];

	int	numservers;

	byte*	buffptr;

	byte*	buffend;



	Com_Printf( "CL_ServersResponsePacket\n" );



	if ( cls.numglobalservers == -1 ) {

		// state to detect lack of servers or lack of response

		cls.numglobalservers = 0;

		cls.numGlobalServerAddresses = 0;

	}



	// parse through server response string

	numservers = 0;

	buffptr    = msg->data;

	buffend    = buffptr + msg->cursize;



	// advance to initial token

	do

	{

		if(*buffptr == '\\' || (extended && *buffptr == '/'))

			break;



		buffptr++;

	} while (buffptr < buffend);



	while (buffptr + 1 < buffend)

	{

		// IPv4 address

		if (*buffptr == '\\')

		{

			buffptr++;



			if (buffend - buffptr < sizeof(addresses[numservers].ip) + sizeof(addresses[numservers].port) + 1)

				break;



			for(i = 0; i < sizeof(addresses[numservers].ip); i++)

				addresses[numservers].ip[i] = *buffptr++;



			addresses[numservers].type = NA_IP;

		}

		// IPv6 address, if it's an extended response

		else if (extended && *buffptr == '/')

		{

			buffptr++;



			if (buffend - buffptr < sizeof(addresses[numservers].ip6) + sizeof(addresses[numservers].port) + 1)

				break;



			for(i = 0; i < sizeof(addresses[numservers].ip6); i++)

				addresses[numservers].ip6[i] = *buffptr++;



			addresses[numservers].type = NA_IP6;

			addresses[numservers].scope_id = from->scope_id;

		}

		else

			// syntax error!

			break;



		// parse out port

		addresses[numservers].port = (*buffptr++) << 8;

		addresses[numservers].port += *buffptr++;

		addresses[numservers].port = BigShort( addresses[numservers].port );



		// syntax check

		if (*buffptr != '\\' && *buffptr != '/')

			break;



		numservers++;



		if (numservers >= MAX_SERVERSPERPACKET)

			break;

	}



	count = cls.numglobalservers;



	for (i = 0; i < numservers && count < MAX_GLOBAL_SERVERS; i++) {

		// build net address

		serverInfo_t *server = &cls.globalServers[count];



		// Tequila: It's possible to have sent many master server requests. Then

		// we may receive many times the same addresses from the master server.

		// We just avoid to add a server if it is still in the global servers list.

		for (j = 0; j < count; j++)

		{

			if (NET_CompareAdr(cls.globalServers[j].adr, addresses[i]))

				break;

		}



		if (j < count)

			continue;



		CL_InitServerInfo( server, &addresses[i] );

		// advance to next slot

		count++;

	}



	// if getting the global list

	if ( count >= MAX_GLOBAL_SERVERS && cls.numGlobalServerAddresses < MAX_GLOBAL_SERVERS )

	{

		// if we couldn't store the servers in the main list anymore

		for (; i < numservers && cls.numGlobalServerAddresses < MAX_GLOBAL_SERVERS; i++)

		{

			// just store the addresses in an additional list

			cls.globalServerAddresses[cls.numGlobalServerAddresses++] = addresses[i];

		}

	}



	cls.numglobalservers = count;

	total = count + cls.numGlobalServerAddresses;



	Com_Printf( "%d servers parsed (total %d)\n", numservers, total );

}



/*

=================

CL_ConnectionlessPacket



Responses to broadcasts, etc

=================

*/

void CL_ConnectionlessPacket( netadr_t from, msg_t *msg ) {

	char	*s;

	char	*c;

	int challenge = 0;



	MSG_BeginReadingOOB( msg );

	MSG_ReadLong( msg );	// skip the -1



	s = MSG_ReadStringLine( msg );



	Cmd_TokenizeString( s );



	c = Cmd_Argv( 0 );



	Com_DPrintf ("CL packet %s: %s\n", NET_AdrToStringwPort(from), c);



	// challenge from the server we are connecting to

	if (!Q_stricmp(c, "challengeResponse"))

	{

		char *strver;

		int ver;



		if (clc.state != CA_CONNECTING)

		{

			Com_DPrintf("Unwanted challenge response received. Ignored.\n");

			return;

		}



		c = Cmd_Argv( 2 );

		if(*c)

			challenge = atoi(c);



		strver = Cmd_Argv( 3 );

		if(*strver)

		{

			ver = atoi(strver);



			if(ver != com_protocol->integer)

			{

#ifdef LEGACY_PROTOCOL

				if(com_legacyprotocol->integer > 0)

				{

					// Server is ioq3 but has a different protocol than we do.

					// Fall back to idq3 protocol.

					clc.compat = qtrue;



					Com_Printf(S_COLOR_YELLOW "Warning: Server reports protocol version %d, "

						   "we have %d. Trying legacy protocol %d.\n",

						   ver, com_protocol->integer, com_legacyprotocol->integer);

				}

				else

#endif

				{

					Com_Printf(S_COLOR_YELLOW "Warning: Server reports protocol version %d, we have %d. "

						   "Trying anyways.\n", ver, com_protocol->integer);

				}

			}

		}

#ifdef LEGACY_PROTOCOL

		else

			clc.compat = qtrue;



		if(clc.compat)

		{

			if(!NET_CompareAdr(from, clc.serverAddress))

			{

				// This challenge response is not coming from the expected address.

				// Check whether we have a matching client challenge to prevent

				// connection hi-jacking.



				if(!*c || challenge != clc.challenge)

				{

					Com_DPrintf("Challenge response received from unexpected source. Ignored.\n");

					return;

				}

			}

		}

		else

#endif

		{

			if(!*c || challenge != clc.challenge)

			{

				Com_Printf("Bad challenge for challengeResponse. Ignored.\n");

				return;

			}

		}



		// start sending challenge response instead of challenge request packets

		clc.challenge = atoi(Cmd_Argv(1));

		clc.state = CA_CHALLENGING;

		clc.connectPacketCount = 0;

		clc.connectTime = -99999;



		// take this address as the new server address.  This allows

		// a server proxy to hand off connections to multiple servers

		clc.serverAddress = from;

		Com_DPrintf ("challengeResponse: %d\n", clc.challenge);

		return;

	}



	// server connection

	if ( !Q_stricmp( c, "connectResponse" ) ) {

		if ( clc.state >= CA_CONNECTED ) {

			Com_Printf( "Dup connect received. Ignored.\n" );

			return;

		}

		if ( clc.state != CA_CHALLENGING ) {

			Com_Printf( "connectResponse packet while not connecting. Ignored.\n" );

			return;

		}

		if ( !NET_CompareAdr( from, clc.serverAddress ) ) {

			Com_Printf( "connectResponse from wrong address. Ignored.\n" );

			return;

		}



#ifdef LEGACY_PROTOCOL

		if(!clc.compat)

#endif

		{

			c = Cmd_Argv(1);



			if(*c)

				challenge = atoi(c);

			else

			{

				Com_Printf("Bad connectResponse received. Ignored.\n");

				return;

			}



			if(challenge != clc.challenge)

			{

				Com_Printf("ConnectResponse with bad challenge received. Ignored.\n");

				return;

			}

		}



#ifdef LEGACY_PROTOCOL

		Netchan_Setup(NS_CLIENT, &clc.netchan, from, Cvar_VariableValue("net_qport"),

			      clc.challenge, clc.compat);

#else

		Netchan_Setup(NS_CLIENT, &clc.netchan, from, Cvar_VariableValue("net_qport"),

			      clc.challenge, qfalse);

#endif



		clc.state = CA_CONNECTED;

		clc.lastPacketSentTime = -9999;	// send first packet immediately

		return;

	}



	// server responding to an info broadcast

	if ( !Q_stricmp( c, "infoResponse" ) ) {

		CL_ServerInfoPacket( from, msg );

		return;

	}



	// server responding to a get playerlist

	if ( !Q_stricmp( c, "statusResponse" ) ) {

		CL_ServerStatusResponse( from, msg );

		return;

	}



	// echo request from server

	if ( !Q_stricmp( c, "echo" ) ) {

		NET_OutOfBandPrint( NS_CLIENT, from, "%s", Cmd_Argv( 1 ) );

		return;

	}



	// cd check

	if ( !Q_stricmp( c, "keyAuthorize" ) ) {

		// we don't use these now, so dump them on the floor

		return;

	}



	// global MOTD from id

	if ( !Q_stricmp( c, "motd" ) ) {

		CL_MotdPacket( from );

		return;

	}



	// echo request from server

	if ( !Q_stricmp( c, "print" ) ) {

		s = MSG_ReadString( msg );



		Q_strncpyz( clc.serverMessage, s, sizeof( clc.serverMessage ) );

		Com_Printf( "%s", s );

		return;

	}



	// list of servers sent back by a master server (classic)

	if ( !Q_strncmp( c, "getserversResponse", 18 ) ) {

		CL_ServersResponsePacket( &from, msg, qfalse );

		return;

	}



	// list of servers sent back by a master server (extended)

	if ( !Q_strncmp(c, "getserversExtResponse", 21) ) {

		CL_ServersResponsePacket( &from, msg, qtrue );

		return;

	}



	Com_DPrintf( "Unknown connectionless packet command.\n" );

}



/*

=================

CL_PacketEvent



A packet has arrived from the main event loop

=================

*/

void CL_PacketEvent( netadr_t from, msg_t *msg ) {

	int	headerBytes;



	clc.lastPacketTime = cls.realtime;



	if ( msg->cursize >= 4 && *(int *)msg->data == -1 ) {

		CL_ConnectionlessPacket( from, msg );

		return;

	}



	if ( clc.state < CA_CONNECTED ) {

		return;	// can't be a valid sequenced packet

	}



	if ( msg->cursize < 4 ) {

		Com_Printf ("%s: Runt packet\n", NET_AdrToStringwPort( from ));

		return;

	}



	//

	// packet from server

	//

	if ( !NET_CompareAdr( from, clc.netchan.remoteAddress ) ) {

		Com_DPrintf( "%s:sequenced packet without connection\n"

			, NET_AdrToStringwPort( from ) );

		// FIXME: send a client disconnect?

		return;

	}



	if ( !CL_Netchan_Process( &clc.netchan, msg ) ) {

		return;	// out of order, duplicated, etc

	}



	// the header is different lengths for reliable and unreliable messages

	headerBytes = msg->readcount;



	// track the last message received so it can be returned in

	// client messages, allowing the server to detect a dropped

	// gamestate

	clc.serverMessageSequence = LittleLong( *(int *)msg->data );



	clc.lastPacketTime = cls.realtime;

	CL_ParseServerMessage( msg );



	//

	// we don't know if it is ok to save a demo message until

	// after we have parsed the frame

	//

	if ( clc.demorecording && !clc.demowaiting ) {

		CL_WriteDemoMessage( msg, headerBytes );

	}

}



/*

==================

CL_CheckTimeout



==================

*/

void CL_CheckTimeout( void ) {

	//

	// check timeout

	//

	if ( ( !CL_CheckPaused() || !sv_paused->integer ) 

		&& clc.state >= CA_CONNECTED && clc.state != CA_CINEMATIC

		&& cls.realtime - clc.lastPacketTime > cl_timeout->value * 1000 ) {

		if ( ++cl.timeoutcount > 5 ) {	// timeoutcount saves debugger

			Com_Printf( "\nServer connection timed out.\n" );

			CL_Disconnect( qtrue );

			return;

		}

	} else {

		cl.timeoutcount = 0;

	}

}



/*

==================

CL_CheckPaused

Check whether client has been paused.

==================

*/

qboolean CL_CheckPaused(void)

{

	// if cl_paused->modified is set, the cvar has only been changed in

	// this frame. Keep paused in this frame to ensure the server doesn't

	// lag behind.

	if(cl_paused->integer || cl_paused->modified)

		return qtrue;



	return qfalse;

}





