/*

==================

CL_CheckUserinfo



==================

*/

void CL_CheckUserinfo( void ) {

	// don't add reliable commands when not yet connected

	if(clc.state < CA_CONNECTED)

		return;



	// don't overflow the reliable command buffer when paused

	if(CL_CheckPaused())

		return;



	// send a reliable userinfo update if needed

	if ( cvar_modifiedFlags & CVAR_USERINFO ) {

		cvar_modifiedFlags &= ~CVAR_USERINFO;

		CL_AddReliableCommand(va("userinfo \"%s\"", Cvar_InfoString( CVAR_USERINFO ) ), qfalse);

	}

}



/*

==================

CL_Frame



==================

*/

void CL_Frame( int msec ) {



	if ( !com_cl_running->integer ) {

		return;

	}



#ifdef USE_CURL

	if(clc.downloadCURLM) {

		CL_cURL_PerformDownload();

		// we can't process frames normally when in disconnected

		// download mode since the ui vm expects clc.state to be

		// CA_CONNECTED

		if(clc.cURLDisconnected) {

			cls.realFrametime = msec;

			cls.frametime = msec;

			cls.realtime += cls.frametime;

			SCR_UpdateScreen();

			S_Update();

			Con_RunConsole();

			cls.framecount++;

			return;

		}

	}

#endif



	if ( cls.cddialog ) {

		// bring up the cd error dialog if needed

		cls.cddialog = qfalse;

		VM_Call( uivm, UI_SET_ACTIVE_MENU, UIMENU_NEED_CD );

	} else if ( cls.endgamemenu ) {

		cls.endgamemenu = qfalse;

		VM_Call( uivm, UI_SET_ACTIVE_MENU, UIMENU_ENDGAME );

	} else	if ( clc.state == CA_DISCONNECTED && !( Key_GetCatcher( ) & KEYCATCH_UI )

		&& !com_sv_running->integer && uivm ) {

		// if disconnected, bring up the menu

		S_StopAllSounds();

		VM_Call( uivm, UI_SET_ACTIVE_MENU, UIMENU_MAIN );

	}



	// if recording an avi, lock to a fixed fps

	if ( ( CL_VideoRecording( ) && cl_aviFrameRate->integer && msec ) || ( cl_avidemo->integer && msec ) ) {

		// save the current screen

		if ( clc.state == CA_ACTIVE || cl_forceavidemo->integer ) {

			if ( cl_avidemo->integer ) {	// Legacy (screenshot) method

				Cbuf_ExecuteText( EXEC_NOW, "screenshot silent\n" );



				// fixed time for next frame

				msec = ( 1000 / cl_avidemo->integer ) * com_timescale->value;

				if ( msec == 0 ) {

					msec = 1;

				}

			} else {			// ioquake3 method

				float fps = MIN(cl_aviFrameRate->value * com_timescale->value, 1000.0f);

				float frameDuration = MAX(1000.0f / fps, 1.0f) + clc.aviVideoFrameRemainder;



				CL_TakeVideoFrame( );



				msec = (int)frameDuration;

				clc.aviVideoFrameRemainder = frameDuration - msec;

			}

		}

	}



	if( cl_autoRecordDemo->integer ) {

		if( clc.state == CA_ACTIVE && !clc.demorecording && !clc.demoplaying ) {

			// If not recording a demo, and we should be, start one

			qtime_t	now;

			char		*nowString;

			char		*p;

			char		mapName[ MAX_QPATH ];

			char		serverName[ MAX_OSPATH ];



			Com_RealTime( &now );

			nowString = va( "%04d%02d%02d%02d%02d%02d",

					1900 + now.tm_year,

					1 + now.tm_mon,

					now.tm_mday,

					now.tm_hour,

					now.tm_min,

					now.tm_sec );



			Q_strncpyz( serverName, clc.servername, MAX_OSPATH );

			// Replace the ":" in the address as it is not a valid

			// file name character

			p = strstr( serverName, ":" );

			if( p ) {

				*p = '.';

			}



			Q_strncpyz( mapName, COM_SkipPath( cl.mapname ), sizeof( cl.mapname ) );

			COM_StripExtension(mapName, mapName, sizeof(mapName));



			Cbuf_ExecuteText( EXEC_NOW,

					va( "record %s-%s-%s", nowString, serverName, mapName ) );

		}

		else if( clc.state != CA_ACTIVE && clc.demorecording ) {

			// Recording, but not CA_ACTIVE, so stop recording

			CL_StopRecord_f( );

		}

	}



	// save the msec before checking pause

	cls.realFrametime = msec;



	// decide the simulation time

	cls.frametime = msec;



	cls.realtime += cls.frametime;



	if ( cl_timegraph->integer ) {

		SCR_DebugGraph ( cls.realFrametime * 0.25 );

	}



	// see if we need to update any userinfo

	CL_CheckUserinfo();



	// if we haven't gotten a packet in a long time,

	// drop the connection

	CL_CheckTimeout();



	// send intentions now

	CL_SendCmd();



	// resend a connection request if necessary

	CL_CheckForResend();



	// decide on the serverTime to render

	CL_SetCGameTime();



	// update the screen

	SCR_UpdateScreen();



	// update audio

	S_Update();



#ifdef USE_VOIP

	CL_CaptureVoip();

#endif



#ifdef USE_MUMBLE

	CL_UpdateMumble();

#endif



	// advance local effects for next frame

	SCR_RunCinematic();



	Con_RunConsole();



	cls.framecount++;

}





