*/

int CL_GetPingQueueCount( void ) {

	int	i;

	int	count;

	ping_t*	pingptr;



	count   = 0;

	pingptr = cl_pinglist;



	for ( i = 0; i < MAX_PINGREQUESTS; i++, pingptr++ ) {

		if ( pingptr->adr.port ) {

			count++;

		}

	}



	return ( count );

