					enum dma_data_direction direction)

{

	struct dma_buf *dmabuf = attachment->dmabuf;

	struct ion_buffer *buffer = dmabuf->priv;



	ion_buffer_sync_for_device(buffer, attachment->dev, direction);

	return buffer->sg_table;

}



