    safe_recv_packet(buffer.bytes, sizeof(buffer.bytes));

    validate_response_header(&buffer.response, PROTOCOL_BINARY_CMD_NOOP,

                             PROTOCOL_BINARY_RESPONSE_SUCCESS);



    return TEST_PASS;

}



