/* generic Control Protocol (e.g. LCP, IPCP, CCP, etc.) handler */

static void

handle_ctrl_proto(netdissect_options *ndo,

                  u_int proto, const u_char *pptr, int length)

{

	const char *typestr;

	u_int code, len;

	int (*pfunc)(netdissect_options *, const u_char *, int);

	int x, j;

        const u_char *tptr;



        tptr=pptr;



        typestr = tok2str(ppptype2str, "unknown ctrl-proto (0x%04x)", proto);

	ND_PRINT((ndo, "%s, ", typestr));



	if (length < 4) /* FIXME weak boundary checking */

		goto trunc;

	ND_TCHECK2(*tptr, 2);



	code = *tptr++;



	ND_PRINT((ndo, "%s (0x%02x), id %u, length %u",

	          tok2str(cpcodes, "Unknown Opcode",code),

	          code,

	          *tptr++, /* ID */

	          length + 2));



	if (!ndo->ndo_vflag)

		return;



	if (length <= 4)

		return;    /* there may be a NULL confreq etc. */



	ND_TCHECK2(*tptr, 2);

	len = EXTRACT_16BITS(tptr);

	tptr += 2;



	ND_PRINT((ndo, "\n\tencoded length %u (=Option(s) length %u)", len, len - 4));



	if (ndo->ndo_vflag > 1)

		print_unknown_data(ndo, pptr - 2, "\n\t", 6);





	switch (code) {

	case CPCODES_VEXT:

		if (length < 11)

			break;

		ND_TCHECK2(*tptr, 4);

		ND_PRINT((ndo, "\n\t  Magic-Num 0x%08x", EXTRACT_32BITS(tptr)));

		tptr += 4;

		ND_TCHECK2(*tptr, 3);

		ND_PRINT((ndo, " Vendor: %s (%u)",

                       tok2str(oui_values,"Unknown",EXTRACT_24BITS(tptr)),

                       EXTRACT_24BITS(tptr)));

		/* XXX: need to decode Kind and Value(s)? */

		break;

	case CPCODES_CONF_REQ:

	case CPCODES_CONF_ACK:

	case CPCODES_CONF_NAK:

	case CPCODES_CONF_REJ:

		x = len - 4;	/* Code(1), Identifier(1) and Length(2) */

		do {

			switch (proto) {

			case PPP_LCP:

				pfunc = print_lcp_config_options;

				break;

			case PPP_IPCP:

				pfunc = print_ipcp_config_options;

				break;

			case PPP_IPV6CP:

				pfunc = print_ip6cp_config_options;

				break;

			case PPP_CCP:

				pfunc = print_ccp_config_options;

				break;

			case PPP_BACP:

				pfunc = print_bacp_config_options;

				break;

			default:

				/*

				 * No print routine for the options for

				 * this protocol.

				 */

				pfunc = NULL;

				break;

			}



			if (pfunc == NULL) /* catch the above null pointer if unknown CP */

				break;



			if ((j = (*pfunc)(ndo, tptr, len)) == 0)

				break;

			x -= j;

			tptr += j;

		} while (x > 0);

		break;



	case CPCODES_TERM_REQ:

	case CPCODES_TERM_ACK:

		/* XXX: need to decode Data? */

		break;

	case CPCODES_CODE_REJ:

		/* XXX: need to decode Rejected-Packet? */

		break;

	case CPCODES_PROT_REJ:

		if (length < 6)

			break;

		ND_TCHECK2(*tptr, 2);

		ND_PRINT((ndo, "\n\t  Rejected %s Protocol (0x%04x)",

		       tok2str(ppptype2str,"unknown", EXTRACT_16BITS(tptr)),

		       EXTRACT_16BITS(tptr)));

		/* XXX: need to decode Rejected-Information? - hexdump for now */

		if (len > 6) {

			ND_PRINT((ndo, "\n\t  Rejected Packet"));

			print_unknown_data(ndo, tptr + 2, "\n\t    ", len - 2);

		}

		break;

	case CPCODES_ECHO_REQ:

	case CPCODES_ECHO_RPL:

	case CPCODES_DISC_REQ:

		if (length < 8)

			break;

		ND_TCHECK2(*tptr, 4);

		ND_PRINT((ndo, "\n\t  Magic-Num 0x%08x", EXTRACT_32BITS(tptr)));

		/* XXX: need to decode Data? - hexdump for now */

		if (len > 8) {

			ND_PRINT((ndo, "\n\t  -----trailing data-----"));

			ND_TCHECK2(tptr[4], len - 8);

			print_unknown_data(ndo, tptr + 4, "\n\t  ", len - 8);

		}

		break;

	case CPCODES_ID:

		if (length < 8)

			break;

		ND_TCHECK2(*tptr, 4);

		ND_PRINT((ndo, "\n\t  Magic-Num 0x%08x", EXTRACT_32BITS(tptr)));

		/* RFC 1661 says this is intended to be human readable */

		if (len > 8) {

			ND_PRINT((ndo, "\n\t  Message\n\t    "));

			if (fn_printn(ndo, tptr + 4, len - 4, ndo->ndo_snapend))

				goto trunc;

		}

		break;

	case CPCODES_TIME_REM:

		if (length < 12)

			break;

		ND_TCHECK2(*tptr, 4);

		ND_PRINT((ndo, "\n\t  Magic-Num 0x%08x", EXTRACT_32BITS(tptr)));

		ND_TCHECK2(*(tptr + 4), 4);

		ND_PRINT((ndo, ", Seconds-Remaining %us", EXTRACT_32BITS(tptr + 4)));

		/* XXX: need to decode Message? */

		break;

	default:

		/* XXX this is dirty but we do not get the

		 * original pointer passed to the begin

		 * the PPP packet */

		if (ndo->ndo_vflag <= 1)

			print_unknown_data(ndo, pptr - 2, "\n\t  ", length + 2);

		break;

	}

	return;



trunc:

	ND_PRINT((ndo, "[|%s]", typestr));

}



/* LCP config options */

static int

print_lcp_config_options(netdissect_options *ndo,

                         const u_char *p, int length)

{

	int len, opt;



	if (length < 2)

		return 0;

	ND_TCHECK2(*p, 2);

	len = p[1];

	opt = p[0];

	if (length < len)

		return 0;

	if (len < 2) {

		if ((opt >= LCPOPT_MIN) && (opt <= LCPOPT_MAX))

			ND_PRINT((ndo, "\n\t  %s Option (0x%02x), length %u (length bogus, should be >= 2)",

			          lcpconfopts[opt], opt, len));

		else

			ND_PRINT((ndo, "\n\tunknown LCP option 0x%02x", opt));

		return 0;

	}

	if ((opt >= LCPOPT_MIN) && (opt <= LCPOPT_MAX))

		ND_PRINT((ndo, "\n\t  %s Option (0x%02x), length %u", lcpconfopts[opt], opt, len));

	else {

		ND_PRINT((ndo, "\n\tunknown LCP option 0x%02x", opt));

		return len;

	}



	switch (opt) {

	case LCPOPT_VEXT:

		if (len < 6) {

			ND_PRINT((ndo, " (length bogus, should be >= 6)"));

			return len;

		}

		ND_TCHECK2(*(p + 2), 3);

		ND_PRINT((ndo, ": Vendor: %s (%u)",

			tok2str(oui_values,"Unknown",EXTRACT_24BITS(p+2)),

			EXTRACT_24BITS(p + 2)));

#if 0

		ND_TCHECK(p[5]);

		ND_PRINT((ndo, ", kind: 0x%02x", p[5]));

		ND_PRINT((ndo, ", Value: 0x"));

		for (i = 0; i < len - 6; i++) {

			ND_TCHECK(p[6 + i]);

			ND_PRINT((ndo, "%02x", p[6 + i]));

		}

#endif

		break;

	case LCPOPT_MRU:

		if (len != 4) {

			ND_PRINT((ndo, " (length bogus, should be = 4)"));

			return len;

		}

		ND_TCHECK2(*(p + 2), 2);

		ND_PRINT((ndo, ": %u", EXTRACT_16BITS(p + 2)));

		break;

	case LCPOPT_ACCM:

		if (len != 6) {

			ND_PRINT((ndo, " (length bogus, should be = 6)"));

			return len;

		}

		ND_TCHECK2(*(p + 2), 4);

		ND_PRINT((ndo, ": 0x%08x", EXTRACT_32BITS(p + 2)));

		break;

	case LCPOPT_AP:

		if (len < 4) {

			ND_PRINT((ndo, " (length bogus, should be >= 4)"));

			return len;

		}

		ND_TCHECK2(*(p + 2), 2);

		ND_PRINT((ndo, ": %s", tok2str(ppptype2str, "Unknown Auth Proto (0x04x)", EXTRACT_16BITS(p + 2))));



		switch (EXTRACT_16BITS(p+2)) {

		case PPP_CHAP:

			ND_TCHECK(p[4]);

			ND_PRINT((ndo, ", %s", tok2str(authalg_values, "Unknown Auth Alg %u", p[4])));

			break;

		case PPP_PAP: /* fall through */

		case PPP_EAP:

		case PPP_SPAP:

		case PPP_SPAP_OLD:

                        break;

		default:

			print_unknown_data(ndo, p, "\n\t", len);

		}

		break;

	case LCPOPT_QP:

		if (len < 4) {

			ND_PRINT((ndo, " (length bogus, should be >= 4)"));

			return 0;

		}

		ND_TCHECK2(*(p + 2), 2);

		if (EXTRACT_16BITS(p+2) == PPP_LQM)

			ND_PRINT((ndo, ": LQR"));

		else

			ND_PRINT((ndo, ": unknown"));

		break;

	case LCPOPT_MN:

		if (len != 6) {

			ND_PRINT((ndo, " (length bogus, should be = 6)"));

			return 0;

		}

		ND_TCHECK2(*(p + 2), 4);

		ND_PRINT((ndo, ": 0x%08x", EXTRACT_32BITS(p + 2)));

		break;

	case LCPOPT_PFC:

		break;

	case LCPOPT_ACFC:

		break;

	case LCPOPT_LD:

		if (len != 4) {

			ND_PRINT((ndo, " (length bogus, should be = 4)"));

			return 0;

		}

		ND_TCHECK2(*(p + 2), 2);

		ND_PRINT((ndo, ": 0x%04x", EXTRACT_16BITS(p + 2)));

		break;

	case LCPOPT_CBACK:

		if (len < 3) {

			ND_PRINT((ndo, " (length bogus, should be >= 3)"));

			return 0;

		}

		ND_PRINT((ndo, ": "));

		ND_TCHECK(p[2]);

		ND_PRINT((ndo, ": Callback Operation %s (%u)",

                       tok2str(ppp_callback_values, "Unknown", p[2]),

                       p[2]));

		break;

	case LCPOPT_MLMRRU:

		if (len != 4) {

			ND_PRINT((ndo, " (length bogus, should be = 4)"));

			return 0;

		}

		ND_TCHECK2(*(p + 2), 2);

		ND_PRINT((ndo, ": %u", EXTRACT_16BITS(p + 2)));

		break;

	case LCPOPT_MLED:

		if (len < 3) {

			ND_PRINT((ndo, " (length bogus, should be >= 3)"));

			return 0;

		}

		ND_TCHECK(p[2]);

		switch (p[2]) {		/* class */

		case MEDCLASS_NULL:

			ND_PRINT((ndo, ": Null"));

			break;

		case MEDCLASS_LOCAL:

			ND_PRINT((ndo, ": Local")); /* XXX */

			break;

		case MEDCLASS_IPV4:

			if (len != 7) {

				ND_PRINT((ndo, " (length bogus, should be = 7)"));

				return 0;

			}

			ND_TCHECK2(*(p + 3), 4);

			ND_PRINT((ndo, ": IPv4 %s", ipaddr_string(ndo, p + 3)));

			break;

		case MEDCLASS_MAC:

			if (len != 9) {

				ND_PRINT((ndo, " (length bogus, should be = 9)"));

				return 0;

			}

			ND_TCHECK2(*(p + 3), 6);

			ND_PRINT((ndo, ": MAC %s", etheraddr_string(ndo, p + 3)));

			break;

		case MEDCLASS_MNB:

			ND_PRINT((ndo, ": Magic-Num-Block")); /* XXX */

			break;

		case MEDCLASS_PSNDN:

			ND_PRINT((ndo, ": PSNDN")); /* XXX */

			break;

		default:

			ND_PRINT((ndo, ": Unknown class %u", p[2]));

			break;

		}

		break;



/* XXX: to be supported */

#if 0

	case LCPOPT_DEP6:

	case LCPOPT_FCSALT:

	case LCPOPT_SDP:

	case LCPOPT_NUMMODE:

	case LCPOPT_DEP12:

	case LCPOPT_DEP14:

	case LCPOPT_DEP15:

	case LCPOPT_DEP16:

        case LCPOPT_MLSSNHF:

	case LCPOPT_PROP:

	case LCPOPT_DCEID:

	case LCPOPT_MPP:

	case LCPOPT_LCPAOPT:

	case LCPOPT_COBS:

	case LCPOPT_PE:

	case LCPOPT_MLHF:

	case LCPOPT_I18N:

	case LCPOPT_SDLOS:

	case LCPOPT_PPPMUX:

		break;

#endif

	default:

		/*

		 * Unknown option; dump it as raw bytes now if we're

		 * not going to do so below.

		 */

		if (ndo->ndo_vflag < 2)

			print_unknown_data(ndo, &p[2], "\n\t    ", len - 2);

		break;

	}



	if (ndo->ndo_vflag > 1)

		print_unknown_data(ndo, &p[2], "\n\t    ", len - 2); /* exclude TLV header */



	return len;



trunc:

	ND_PRINT((ndo, "[|lcp]"));

	return 0;

}



