	}

	if (ndo->ndo_vflag > 1)

		print_unknown_data(ndo, &p[2], "\n\t    ", len - 2); /* exclude TLV header */

	return len;



trunc:

	ND_PRINT((ndo, "[|ipcp]"));

	return 0;

}



